import os, pty, sys, time, select, fcntl, termios, struct, re

def run(args, w=100, h=20, seq=None, out=sys.stdout.buffer):
    pid, fd = pty.fork()
    if pid == 0:
        os.environ['TERM'] = 'xterm-256color'
        os.environ['COLUMNS'] = str(w); os.environ['LINES'] = str(h)
        os.execv('/workspace/executable', ['/workspace/executable'] + args)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', h, w, 0, 0))
    buf = []
    def drain(t):
        end = time.time() + t
        while time.time() < end:
            r, _, _ = select.select([fd], [], [], 0.05)
            if r:
                try:
                    data = os.read(fd, 65536)
                except OSError:
                    break
                if not data: break
                buf.append(data)
    drain(0.5)
    if seq:
        for item in seq:
            if isinstance(item, float):
                drain(item)
            elif isinstance(item, str):
                os.write(fd, item.encode())
    drain(0.8)
    try:
        os.kill(pid, 9)
    except ProcessLookupError:
        pass
    out.write(b''.join(buf))

if __name__ == '__main__':
    args = sys.argv[1:]
    # parse simple key spec: "sleep:1" or "key:<keys>"
    seq = []
    plain = []
    i = 0
    while i < len(args):
        if args[i] == '--sleep' or args[i] == '-s':
            seq.append(float(args[i+1])); i += 2
        elif args[i] == '--key' or args[i] == '-k':
            seq.append(args[i+1]); i += 2
        else:
            plain.append(args[i]); i += 1
    run(plain, seq=seq)
EOF
