/// LCS based diff over sequences of strings producing hunks
#[derive(Debug, Clone, PartialEq)]
pub enum Op {
    Common(usize, usize),
    Remove(usize),
    Add(usize),
}

pub fn lcs_diff<T: PartialEq + Clone>(a: &[T], b: &[T]) -> Vec<Op> {
    let n = a.len();
    let m = b.len();
    // table of lengths
    let mut dp = vec![vec![0usize; m + 1]; n + 1];
    for i in (0..n).rev() {
        for j in (0..m).rev() {
            dp[i][j] = if a[i] == b[j] {
                dp[i + 1][j + 1] + 1
            } else {
                std::cmp::max(dp[i + 1][j], dp[i][j + 1])
            };
        }
    }
    let mut ops = Vec::new();
    let mut i = 0;
    let mut j = 0;
    while i < n && j < m {
        if a[i] == b[j] {
            ops.push(Op::Common(i, j));
            i += 1;
            j += 1;
        } else if dp[i + 1][j] >= dp[i][j + 1] {
            ops.push(Op::Remove(i));
            i += 1;
        } else {
            ops.push(Op::Add(j));
            j += 1;
        }
    }
    while i < n {
        ops.push(Op::Remove(i));
        i += 1;
    }
    while j < m {
        ops.push(Op::Add(j));
        j += 1;
    }
    ops
}

/// Split a line into "words": each token is a word plus its trailing whitespace
pub fn split_words(line: &str) -> Vec<&str> {
    let mut out = Vec::new();
    let mut start = 0;
    let mut in_word = false;
    for (i, ch) in line.char_indices() {
        if ch == ' ' || ch == '\t' {
            if in_word {
                out.push(&line[start..i]);
                in_word = false;
                start = i;
            }
        } else if !in_word {
            in_word = true;
        }
    }
    if start < line.len() {
        out.push(&line[start..]);
    }
    out
}
EOF
echo ok"}

