use crate::diff::*;
use crate::result::ResultData;

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum DiffMode {
    None,
    Watch,
    Line,
    Word,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum OutputMode {
    Output,
    Stdout,
    Stderr,
}

/// Compute the raw change-mask for the watch diff: (pos, changed, display_char)
pub fn watch_mask(prev_line: &str, cur_line: &str) -> Vec<(bool, char)> {
    let pc: Vec<char> = prev_line.chars().collect();
    let cc: Vec<char> = cur_line.chars().collect();
    let n = std::cmp::max(pc.len(), cc.len());
    let mut out = Vec::new();
    for i in 0..n {
        let c = cc.get(i).copied().unwrap_or(' ');
        let changed = if i < pc.len() && i < cc.len() {
            pc[i] != c
        } else {
            true
        };
        out.push((changed, c));
    }
    out
}

/// Word-level mask used for line/word diff highlight spans
pub fn word_spans(prev_line: &str, cur_line: &str) -> Vec<(String, bool)> {
    let pw = split_words(prev_line);
    let cw = split_words(cur_line);
    let ops = lcs_diff(&pw, &cw);
    // build spans for cur line: (text, changed)
    let mut spans = Vec::new();
    let mut prev_removed = false;
    for op in ops {
        match op {
            Op::Common(_, j) => {
                spans.push((cw[j].to_string(), false));
                prev_removed = false;
            }
            Op::Add(j) => {
                spans.push((cw[j].to_string(), true));
            }
            Op::Remove(_) => {
                prev_removed = true;
            }
        }
    }
    spans
}

/// Line level diff returning ops over lines
pub fn line_ops(prev_lines: &[&str], cur_lines: &[&str]) -> Vec<Op> {
    lcs_diff(prev_lines, cur_lines)
}
