cat > src/batch.rs <<'EOF'
use crate::app::{DiffMode, watch_mask};
use crate::result::ResultData;

pub fn header_line(timestamp: &str) -> String {
    format!("\x1b[38;5;240m=====[{}]=========================\x1b[0m", timestamp)
}

/// Render one result for batch mode
pub fn render_result(result: &ResultData, prev: &ResultData, diff_mode: DiffMode, diff_output_only: bool) -> String {
    let mut out = String::new();
    out.push_str(&header_line(&result.timestamp));
    out.push('\n');
    match diff_mode {
        DiffMode::None => {
            out.push_str(&result.output);
        }
        DiffMode::Watch => {
            let prev_lines: Vec<&str> = prev.output.split('\n').collect();
            let cur_lines: Vec<&str> = result.output.split('\n').collect();
            // ignore trailing empty from final newline
            let cur = trim_trailing(&cur_lines);
            let prev = trim_trailing(&prev_lines);
            let n = std::cmp::max(prev.len(), cur.len());
            for i in 0..n {
                let p = prev.get(i).copied().unwrap_or("");
                let c = cur.get(i).copied().unwrap_or("");
                let mask = watch_mask(p, c);
                if mask.is_empty() {
                    out.push('\n');
                    continue;
                }
                let mut changed = false;
                for (ch, c2) in &mask {
                    if *ch {
                        changed = true;
                        out.push_str("\x1b[7m");
                        out.push(*c2);
                    } else {
                        out.push(*c2);
                    }
                }
                if changed {
                    out.push_str("\x1b[7m\x1b[0m");
                }
                out.push('\n');
            }
        }
        DiffMode::Line | DiffMode::Word => {
            let prev_lines: Vec<&str> = trim_trailing(&prev.output.split('\n').collect::<Vec<&str>>());
            let cur_lines: Vec<&str> = trim_trailing(&result.output.split('\n').collect::<Vec<&str>>());
            let ops = crate::diff::lcs_diff(&prev_lines, &cur_lines);
            for op in ops {
                match op {
                    crate::diff::Op::Common(_, j) => {
                        if diff_output_only {
                            continue;
                        }
                        out.push_str("   ");
                        out.push_str(cur_lines[j]);
                        out.push('\n');
                    }
                    crate::diff::Op::Add(j) => {
                        out.push_str("\x1b[32m+  \x1b[0m");
                        render_line_diff(&cur_lines[j], &cur_lines[j], true, DiffMode::Line);
                        out.push_str(&line_text(&cur_lines[j], true, diff_mode));
                        out.push('\n');
                    }
                    crate::diff::Op::Remove(i) => {
                        out.push_str("\x1b[31m-  \x1b[0m");
                        out.push_str(&line_text(&prev_lines[i], false, diff_mode));
                        out.push('\n');
                    }
                }
            }
        }
    }
    out.push('\n');
    out
}

fn trim_trailing(v: &[&str]) -> Vec<&str> {
    let mut out = v.to_vec();
    while out.len() > 1 && out.last() == Some(&"") {
        out.pop();
    }
    out
}

fn line_text(text: &str, added: bool, diff_mode: DiffMode) -> String {
    let color = if added { "32" } else { "31" };
    match diff_mode {
        DiffMode::Word => {
            // word-level: highlight the changed words with bg
            let _ = color;
            String::new()
        }
        _ => format!("\x1b[{}m{}\x1b[0m", color, text),
    }
}
EOF
echo ok"}

