use clap::ArgMatches;
use clap::Command;
use clap::error::ErrorKind;

fn main() {
    let mut args: Vec<String> = std::env::args().skip(1).collect();
    if let Ok(env_args) = std::env::var("HWATCH") {
        for a in env_args.split_whitespace() {
            args.push(a.to_string());
        }
    }
    let matches = cli::command().try_get_matches_from(args);
    let matches = match matches {
        Ok(m) => m,
        Err(e) => {
            let _ = e.print();
            std::process::exit(e.exit_code());
        }
    };
    if let Err(e) = run(&matches) {
        std::process::exit(e);
    }
}

fn run(m: &ArgMatches) -> Result<i32, i32> {
    let command = m.get_many::<String>("command")
        .map(|v| v.map(|s| s.to_string()).collect::<Vec<_>>().join(" "))
        .unwrap_or_default();
    let logfile = m.get_one::<String>("logfile").cloned();
    if command.is_empty() && logfile.is_none() {
        print_no_command_error();
        return Err(2);
    }
    Ok(0)
}

fn is_tty() -> bool {
    unsafe { libc_isatty(2) == 1 }
}
unsafe fn libc_isatty(fd: i32) -> i32 {
    extern "C" { fn isatty(fd: i32) -> i32; }
    isatty(fd)
}

pub fn err_prefix() -> &'static str {
    if is_tty() { "\x1b[1m\x1b[31m" } else { "" }
}
pub fn err_reset() -> &'static str {
    if is_tty() { "\x1b[0m" } else { "" }
}
pub fn err_bold() -> &'static str {
    if is_tty() { "\x1b[1m" } else { "" }
}
pub fn err_underline() -> &'static str {
    if is_tty() { "\x1b[4m" } else { "" }
}
pub fn err_yellow() -> &'static str {
    if is_tty() { "\x1b[33m" } else { "" }
}

pub fn print_no_command_error() {
    eprintln!("{}error:{} command not specified and logfile is empty.", err_prefix(), err_reset());
    eprintln!();
    eprintln!("{}Usage:{} {}hwatch{} [OPTIONS] [command]...", err_underline(), err_reset(), err_bold(), err_reset());
    eprintln!();
    eprintln!("For more information, try '{}--help{}'.", err_bold(), err_reset());
}
