use std::process::{Command as SysCommand, Stdio};
use std::sync::{Arc, Mutex};
use std::io::Read;

use crate::result::ResultData;
use crate::app::now_string;

/// Build the argv used to run the command
pub fn build_argv(command: &str, shell: &str, exec_mode: bool) -> Vec<String> {
    if exec_mode {
        return command.split_whitespace().map(|s| s.to_string()).collect();
    }
    let v: Vec<String> = shell.split_whitespace().map(|s| s.to_string()).collect();
    if shell.contains("{COMMAND}") {
        let mut out = Vec::new();
        for a in v {
            out.push(a.replace("{COMMAND}", command));
        }
        return out;
    }
    let mut v = v;
    v.push(command.to_string());
    v
}

/// Run the command, capturing output.
pub fn run(command: &str, shell: &str, exec_mode: bool) -> (ResultData, Option<std::io::Error>) {
    let argv = build_argv(command, shell, exec_mode);
    let mut res = ResultData::default();
    res.command = command.to_string();
    if argv.is_empty() {
        return (res, Some(std::io::Error::new(std::io::ErrorKind::Other, "empty command")));
    }
    let mut cmd = SysCommand::new(&argv[0]);
    cmd.args(&argv[1..]);
    cmd.stdout(Stdio::piped());
    cmd.stderr(Stdio::piped());
    let mut child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => return (res, Some(e)),
    };
    let mut stdout_pipe = child.stdout.take().unwrap();
    let mut stderr_pipe = child.stderr.take().unwrap();
    let out_buf = Arc::new(Mutex::new(Vec::<u8>::new()));
    let so = Arc::new(Mutex::new(Vec::<u8>::new()));
    let se = Arc::new(Mutex::new(Vec::<u8>::new()));
    let (o1, o2, so_c, se_c) = (out_buf.clone(), out_buf.clone(), so.clone(), se.clone());
    let t1 = std::thread::spawn(move || {
        let mut buf = [0u8; 8192];
        loop {
            match stdout_pipe.read(&mut buf) {
                Ok(0) => break,
                Ok(n) => {
                    o1.lock().unwrap().extend_from_slice(&buf[..n]);
                    so_c.lock().unwrap().extend_from_slice(&buf[..n]);
                }
                Err(_) => break,
            }
        }
    });
    let t2 = std::thread::spawn(move || {
        let mut buf = [0u8; 8192];
        loop {
            match stderr_pipe.read(&mut buf) {
                Ok(0) => break,
                Ok(n) => {
                    o2.lock().unwrap().extend_from_slice(&buf[..n]);
                    se_c.lock().unwrap().extend_from_slice(&buf[..n]);
                }
                Err(_) => break,
            }
        }
    });
    let status = child.wait();
    let _ = t1.join();
    let _ = t2.join();
    res.stdout = String::from_utf8_lossy(&so.lock().unwrap().clone()).to_string();
    res.stderr = String::from_utf8_lossy(&se.lock().unwrap().clone()).to_string();
    res.output = String::from_utf8_lossy(&out_buf.lock().unwrap().clone()).to_string();
    res.status = match &status { Ok(s) => s.success(), Err(_) => false };
    res.timestamp = now_string();
    (res, None)
}
