use crate::diff::*;
use crate::result::ResultData;

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum DiffMode {
    None,
    Watch,
    Line,
    Word,
}

impl DiffMode {
    pub fn label(&self) -> &'static str {
        match self {
            DiffMode::None => "None      ",
            DiffMode::Watch => "Watch     ",
            DiffMode::Line => "Line      ",
            DiffMode::Word => "Word      ",
        }
    }
    pub fn next(&self) -> DiffMode {
        match self {
            DiffMode::None => DiffMode::Watch,
            DiffMode::Watch => DiffMode::Line,
            DiffMode::Line => DiffMode::Word,
            DiffMode::Word => DiffMode::None,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum OutputMode {
    Output,
    Stdout,
    Stderr,
}

impl OutputMode {
    pub fn label(&self) -> &'static str {
        match self {
            OutputMode::Output => "Output",
            OutputMode::Stdout => "Stdout",
            OutputMode::Stderr => "Stderr",
        }
    }
    pub fn next(&self) -> OutputMode {
        match self {
            OutputMode::Output => OutputMode::Stdout,
            OutputMode::Stdout => OutputMode::Stderr,
            OutputMode::Stderr => OutputMode::Output,
        }
    }
    pub fn from_str(s: &str) -> OutputMode {
        match s {
            "stdout" => OutputMode::Stdout,
            "stderr" => OutputMode::Stderr,
            _ => OutputMode::Output,
        }
    }
    pub fn from_str_opt(s: &str) -> OutputMode {
        match s {
            "stdout" => OutputMode::Stdout,
            "stderr" => OutputMode::Stderr,
            _ => OutputMode::Output,
        }
    }
