pub fn now_string() -> String {
    let now = chrono::Local::now();
    format!(
        "{:04}-{:02}-{:02} {:02}:{:02}:{:02}.{:03}",
        now.year(), now.month(), now.day(), now.hour(), now.minute(), now.second(),
