use crate::app::{DiffMode, split_lines, watch_mask};
use crate::diff::{lcs_diff, Op};
use crate::result::ResultData;

pub fn header_line(timestamp: &str) -> String {
    format!("\x1b[38;5;240m=====[{}]=========================\x1b[0m", timestamp)
}

fn color_of(added: bool) -> &'static str {
    if added { "32" } else { "31" }
}

/// Build the spans for one side of a modified line pair
pub fn modified_spans(text: &str, other: &str, side_is_current: bool) -> Vec<(String, bool)> {
    let pc: Vec<char> = other.chars().collect();
    let cc: Vec<char> = text.chars().collect();
    let n = std::cmp::max(pc.len(), cc.len());
    let mut cur_flags = vec![false; n];
    let mut other_flags = vec![false; n];
    for i in 0..n {
        let a = pc.get(i).copied();
        let b = cc.get(i).copied();
        match (a, b) {
            (Some(x), Some(y)) => {
                if x != y {
                    cur_flags[i] = true;
                    other_flags[i] = true;
                }
            }
            _ => {}
        }
    }
    // build runs
    let src_flags = if side_is_current { &cur_flags } else { &other_flags };
    let mut spans: Vec<(String, bool)> = Vec::new();
    let mut i = 0;
    let len = if side_is_current { cc.len() } else { pc.len() };
    let mut start = 0usize;
    while i < len {
        if src_flags[i] {
            if start < i {
                spans.push((chars_of(text, start, i), false));
            }
            let mut j = i;
            while j < len && src_flags[j] { j += 1; }
            spans.push((chars_of(text, i, j), true));
            i = j;
            start = i;
        } else {
            i += 1;
        }
    }
    if start < len {
        spans.push((chars_of(text, start, len), false));
    }
    spans
}

fn chars_of(s: &str, a: usize, b: usize) -> String {
    s.chars().skip(a).take(b - a).collect()
}

/// Render the changed line for batch mode
pub fn render_changed_line(text: &str, other: &str, added: bool, diff_mode: DiffMode, side_is_current: bool) -> String {
    let c = color_of(added);
    let prefix = if added { "+  " } else { "-  " };
    let mut out = format!("\x1b[{}m{}\x1b[0m", c, prefix);
    let spans = modified_spans(text, other, side_is_current);
    let mut changed_any = false;
    for (s, hl) in &spans {
        if *hl { changed_any = true; }
    }
    match diff_mode {
        DiffMode::Word => {
            for (s, hl) in &spans {
                if *hl {
                    let bg = if added { "42" } else { "41" };
                    out.push_str(&format!("\x1b[{};37m{}\x1b[0m", bg, s));
                } else {
                    out.push_str(&format!("\x1b[{}m{}\x1b[0m", c, s));
                }
            }
            if changed_any {
                out.push_str(&format!("\x1b[{}m\x1b[0m", c));
            }
        }
        _ => {
            for (s, hl) in &spans {
                out.push_str(&format!("\x1b[{}m{}\x1b[0m", c, s));
            }
            if changed_any && spans.last().map(|x| x.1).unwrap_or(false) {
                out.push_str(&format!("\x1b[{}m\x1b[0m", c));
            }
        }
    }
    out
}

pub fn render_result(result: &ResultData, prev: &ResultData, diff_mode: DiffMode, diff_output_only: bool) -> String {
    let mut out = String::new();
    out.push_str(&header_line(&result.timestamp));
    out.push('\n');
    match diff_mode {
        DiffMode::None => {
            out.push_str(&result.output);
        }
        DiffMode::Watch => {
            let prev_lines = split_lines(&prev.output);
            let cur_lines = split_lines(&result.output);
            let n = std::cmp::max(prev_lines.len(), cur_lines.len());
            for i in 0..n {
                let p = prev_lines.get(i).copied().unwrap_or("");
                let c = cur_lines.get(i).copied().unwrap_or("");
                let mask = watch_mask(p, c);
                if mask.is_empty() { out.push('\n'); continue; }
                let mut changed = false;
                for (ch, c2) in &mask {
                    if *ch { changed = true; out.push_str("\x1b[7m"); }
                    out.push(*c2);
                }
                if changed { out.push_str("\x1b[7m\x1b[0m"); }
                out.push('\n');
            }
        }
        DiffMode::Line | DiffMode::Word => {
            let prev_lines = split_lines(&prev.output);
            let cur_lines = split_lines(&result.output);
            let ops = lcs_diff(&prev_lines, &cur_lines);
            // group ops into hunks
            let mut idx = 0;
            while idx < ops.len() {
                match ops[idx] {
                    Op::Common(_, j) => {
                        if !diff_output_only {
                            out.push_str("   ");
                            out.push_str(cur_lines[j]);
                            out.push('\n');
                        }
                        idx += 1;
                    }
                    Op::Remove(i) => {
                        let mut removes = Vec::new();
                        let mut adds = Vec::new();
                        while idx < ops.len() {
                            match ops[idx] {
                                Op::Remove(k) => { removes.push(k); idx += 1; }
                                _ => break,
                            }
                        }
                        while idx < ops.len() {
                            match ops[idx] {
                                Op::Add(k) => { adds.push(k); idx += 1; }
                                _ => break,
                            }
                        }
                        for (k, r) in removes.iter().enumerate() {
                            if let Some(&a) = adds.get(k) {
                                out.push_str(&render_changed_line(prev_lines[*r], cur_lines[a], false, diff_mode, false));
                            } else {
                                out.push_str(&format!("\x1b[31m-  \x1b[0m\x1b[31m{}\x1b[0m", prev_lines[*r]));
                            }
                            out.push('\n');
                        }
                        for (k, a) in adds.iter().enumerate() {
                            if let Some(&r) = removes.get(k) {
                                out.push_str(&render_changed_line(cur_lines[*a], prev_lines[r], true, diff_mode, true));
                            } else {
                                out.push_str(&format!("\x1b[32m+  \x1b[0m\x1b[32m{}\x1b[0m", cur_lines[*a]));
                            }
                            out.push('\n');
                        }
                    }
                    Op::Add(_) => {
                        let mut adds = Vec::new();
                        while idx < ops.len() {
                            match ops[idx] {
                                Op::Add(k) => { adds.push(k); idx += 1; }
                                _ => break,
                            }
                        }
                        for a in adds {
                            out.push_str(&format!("\x1b[32m+  \x1b[0m\x1b[32m{}\x1b[0m", cur_lines[a]));
                            out.push('\n');
                        }
                    }
                }
            }
        }
    }
    out.push('\n');
    out
}
