use clap::ArgMatches;
use crate::app::{DiffMode, OutputMode, now_string};
use crate::batch::render_result;
use crate::result::ResultData;

fn main() {
    let mut args: Vec<String> = std::env::args().skip(1).collect();
    if let Ok(env_args) = std::env::var("HWATCH") {
        for a in env_args.split_whitespace() {
            args.push(a.to_string());
        }
    }
    let matches = cli::command().try_get_matches_from(args);
    let matches = match matches {
        Ok(m) => m,
        Err(e) => {
            let _ = e.print();
            std::process::exit(e.exit_code());
        }
    };
    if let Err(e) = run(&matches) {
        std::process::exit(e);
    }
}

fn run(m: &ArgMatches) -> Result<i32, i32> {
    let command = m.get_many::<String>("command")
        .map(|v| v.map(|s| s.to_string()).collect::<Vec<_>>().join(" "))
        .unwrap_or_default();
    let logfile: Option<String> = m.get_one::<String>("logfile").cloned();
    if command.is_empty() && logfile.is_none() {
        print_no_command_error();
        return Err(2);
    }

    let batch = m.get_flag("batch");
    let mut history: Vec<ResultData> = Vec::new();

    // logfile setup
    let mut log_file = logger::LogFile::new(logfile.clone());
    if let Some(path) = &logfile {
        match log_file.open() {
            Ok(recs) => {
                history = recs;
            }
            Err(logger::OpenError::NotFound) => {}
            Err(logger::OpenError::EmptyFile) => {
                // prompt
                eprintln!("file \"{}\" is exists and empty.", path);
                eprint!("Log to the same file? (Y/n) ");
                use std::io::Write;
                let _ = std::io::stderr().flush();
                let mut line = String::new();
                if std::io::stdin().read_line(&mut line).is_ok() {
                    let t = line.trim();
                    if t.eq_ignore_ascii_case("n") {
                        return Ok(0);
                    }
                }
            }
        }
    }

    let mut command = command;
    if command.is_empty() {
        // use last log record's command
        command = history.last().map(|r| r.command.clone()).unwrap_or_default();
    }

    let shell = m.get_one::<String>("shell").cloned().unwrap_or_else(|| "sh -c".to_string());
    let exec_mode = m.get_flag("exec");
    let interval: f64 = m.get_one::<String>("interval").and_then(|s| s.parse::<f64>().ok()).unwrap_or(2.0);
    let precise = m.get_flag("precise");
    let limit: usize = m.get_one::<String>("limit").and_then(|s| s.parse::<usize>().ok()).unwrap_or(5000);
    let diff_mode = match m.get_one::<String>("differences").map(|s| s.as_str()) {
        Some("none") => DiffMode::None,
        Some("watch") => DiffMode::Watch,
        Some("line") => DiffMode::Line,
        Some("word") => DiffMode::Word,
        _ => DiffMode::None,
    };
    let diff_output_only = m.get_flag("diff-output-only");
    let after_command: Option<String> = m.get_one::<String>("aftercommand").cloned();
    let beep = m.get_flag("beep");

    let output_mode: OutputMode = match m.get_one::<String>("output").map(|s| s.as_str()) {
        Some("stdout") => OutputMode::Stdout,
        Some("stderr") => OutputMode::Stderr,
        Some("output") => OutputMode::Output,
        _ => OutputMode::Output,
    };
    let _ = output_mode;

    // filter output by mode
    let get_output = |r: &ResultData| match output_mode {
        OutputMode::Output => r.output.clone(),
        OutputMode::Stdout => r.stdout.clone(),
        OutputMode::Stderr => r.stderr.clone(),
    };

    let mut prev: Option<ResultData> = history.last().cloned();
    let mut first = true;

    loop {
        let start = std::time::Instant::now();
        let (res, err) = exec::run(&command, &shell, exec_mode);
        if let Some(e) = err {
            eprintln!("{}", e);
        } else {
            let changed = match &prev {
                None => true,
                Some(p) => get_output(p) != get_output(&res),
            };
            if changed || first {
                if beep {
                    print!("\x07");
                }
                if let Some(ac) = &after_command {
                    let data = format!("{{\"before_result\":{},\"after_result\":{}}}",
                        serde_json::to_string(prev.as_ref().unwrap_or(&ResultData::default())).unwrap_or_default(),
                        serde_json::to_string(&res).unwrap_or_default());
                    std::env::set_var("HWATCH_DATA", data);
                    let _ = std::process::Command::new("sh").arg("-c").arg(ac).status();
                }
                if batch {
                    print!("{}", render_result(&res, prev.as_ref().unwrap_or(&ResultData::default()), diff_mode, diff_output_only));
                    use std::io::Write;
                    let _ = std::io::stdout().flush();
                }
                history.push(res.clone());
                if limit > 0 && history.len() > limit {
                    let excess = history.len() - limit;
                    history.drain(0..excess);
                }
                log_file.append(&res);
                prev = Some(res);
                first = false;
            }
        }
        let elapsed = start.elapsed();
        if precise {
            let target = std::time::Duration::from_millis((interval * 1000.0) as u64);
            if elapsed < target { std::thread::sleep(target - elapsed); }
        } else {
            let iv = std::time::Duration::from_millis((interval * 1000.0) as u64);
            std::thread::sleep(iv);
        }
    }
}

fn is_tty() -> bool {
    unsafe { isatty_c(2) == 1 }
}
unsafe fn isatty_c(fd: i32) -> i32 {
    extern "C" { fn isatty(fd: i32) -> i32; }
    isatty(fd)
}

pub fn err_prefix() -> &'static str {
    if is_tty() { "\x1b[1m\x1b[31m" } else { "" }
}
pub fn err_reset() -> &'static str {
    if is_tty() { "\x1b[0m" } else { "" }
}
pub fn err_bold() -> &'static str {
    if is_tty() { "\x1b[1m" } else { "" }
}
pub fn err_underline() -> &'static str {
    if is_tty() { "\x1b[4m" } else { "" }
}

pub fn print_no_command_error() {
    eprintln!("{}error:{} command not specified and logfile is empty.", err_prefix(), err_reset());
    eprintln!();
    eprintln!("{}Usage:{} {}hwatch{} [OPTIONS] [command]...", err_underline(), err_reset(), err_bold(), err_reset());
    eprintln!();
    eprintln!("For more information, try '{}--help{}'.", err_bold(), err_reset());
}
