use crate::result::ResultData;
use serde::Deserialize;

pub enum OpenError {
    NotFound,
    EmptyFile,
}

pub struct LogFile {
    pub path: Option<String>,
    pub handle: Option<std::fs::File>,
}

#[derive(Deserialize)]
struct Rec {
    timestamp: String,
    command: String,
    status: bool,
    output: String,
    stdout: String,
    stderr: String,
}

impl LogFile {
    pub fn new(path: Option<String>) -> Self {
        LogFile { path, handle: None }
    }

    /// Open the file; if it exists and has records, read them. Returns error kinds.
    pub fn open(&mut self) -> Result<Vec<ResultData>, OpenError> {
        let path = match &self.path {
            Some(p) => p.clone(),
            None => return Ok(Vec::new()),
        };
        match std::fs::metadata(&path) {
            Ok(md) => {
                if md.len() == 0 {
                    return Err(OpenError::EmptyFile);
                }
            }
            Err(_) => return Err(OpenError::NotFound),
        }
        let content = std::fs::read_to_string(&path).unwrap_or_default();
        let mut out = Vec::new();
        for line in content.lines() {
            if line.trim().is_empty() { continue; }
            if let Ok(r) = serde_json::from_str::<Rec>(line) {
                out.push(ResultData {
                    timestamp: r.timestamp,
                    command: r.command,
                    status: r.status,
                    output: r.output,
                    stdout: r.stdout,
                    stderr: r.stderr,
                });
            }
        }
        let f = std::fs::OpenOptions::new().append(true).create(true).open(&path).ok();
        self.handle = f;
        Ok(out)
    }

    pub fn append(&mut self, r: &ResultData) {
        if self.handle.is_none() {
            let path = match &self.path { Some(p) => p.clone(), None => return };
            self.handle = std::fs::OpenOptions::new().append(true).create(true).open(&path).ok();
        }
        if let Some(f) = self.handle.as_mut() {
            use std::io::Write;
            let _ = writeln!(f, "{}", r.to_json_line());
            let _ = f.flush();
        }
    }
}
